const orders = { "PO-1001": 1200, "PO-1002": 450, "PO-1003": 9800 };
const invoices = [
  { number: "INV-2026-001", supplier: "Supplier A Ltd", order: "PO-1001", amount: 1200 },
  { number: "INV-2026-002", supplier: "Supplier B Ltd", order: "PO-1002", amount: 520 },
  { number: "INV-2026-003", supplier: "Supplier C Ltd", order: "PO-1003", amount: 9800 },
  { number: "INV-2026-004", supplier: "Supplier D Ltd", order: "PO-9999", amount: 300 }
];
return invoices.map(i => ({ json: { ...i, order_amount: orders[i.order] ?? null } }));

const AUTO_LIMIT = 2000; // above this amount a human always approves
return $input.all().map(({ json: i }) => {
  let decision, reason;
  if (i.order_amount === null) { decision = "reject-for-completion"; reason = "Purchase order does not exist."; }
  else if (i.amount !== i.order_amount) { decision = "manager-approval"; reason = "Amount does not match the order (" + i.order_amount + " vs " + i.amount + ")."; }
  else if (i.amount > AUTO_LIMIT) { decision = "manager-approval"; reason = "Amount above the limit for automatic pre-check."; }
  else { decision = "precheck-ok"; reason = "Matches the order and is under the limit."; }
  return { json: { ...i, decision, reason, human_approves: true } };
});
